# Let's examine the inputs and outputs to understand the transformation
inputs = ['ezzgu', 'ahiagj', 'wxfv', 'cu', 'yyxkj']
outputs = ['ezzgkvi', 'ahiagj', 'wxfv', 'fkvi', 'chbchbxkj']

print("Input strings:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}'")

print("\nOutput strings:")
for i, outp in enumerate(outputs):
    print(f"  {i}: '{outp}'")

print("\nDifferences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"  {i}: '{inp}' -> '{outp}'")

